SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱瞻基", "aliases": ["明宣宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明宣宗，洪熙元年（1425年）六月，朱瞻基即皇帝位。", "biography": null, "status": "draft", "id": "888fc961-674c-52bf-b645-1351d5637434"}, {"name": "朱棣", "aliases": ["明成祖"], "era": "明", "birth_year": null, "death_year": null, "description": "明成祖，建文4年（1402年），朱棣即皇帝位。", "biography": null, "status": "draft", "id": "dd806a37-77e8-5244-96e9-4d71db81b600"}, {"name": "张氏（明仁宗诚孝昭皇后）", "aliases": ["诚孝昭皇后"], "era": "明", "birth_year": null, "death_year": null, "description": "张氏是朱高炽的妃，朱高炽即位后册立她为皇后。", "biography": null, "status": "draft", "id": "d98838f2-35b9-58ff-8f19-a2588ec64e18"}, {"name": "胡善祥", "aliases": ["恭让章皇后"], "era": "明", "birth_year": null, "death_year": null, "description": "胡善祥被立为皇后。", "biography": null, "status": "draft", "id": "899c42d7-6f22-5ca0-a482-61161e914b39"}, {"name": "顾兴祖", "aliases": ["顾兴祖（镇远侯）"], "era": "明", "birth_year": null, "death_year": null, "description": "顾兴祖率军在大藤峡作战。", "biography": null, "status": "draft", "id": "0a604536-ae07-59c2-9b96-854c39af9d0c"}, {"name": "吴成", "aliases": ["吴买驴", "清平伯"], "era": "明", "birth_year": null, "death_year": null, "description": "吴成以清平伯身份率军巡边。", "biography": null, "status": "draft", "id": "5928c61f-6a68-5715-9a6b-3245f0b2427c"}, {"name": "杨溥（明代内阁大学士）", "aliases": ["楊溥"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，洪熙元年（1425年）闰七月，杨溥以太常卿兼翰林学士身份共同处理内阁事务。", "biography": null, "status": "draft", "id": "1f1bfa42-5ca4-5450-84a8-f7927b05b3f7"}, {"name": "朱高炽", "aliases": ["明仁宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明仁宗，永樂22年（1424年）八月，朱高炽即皇帝位。", "biography": null, "status": "draft", "id": "2dded14d-7183-56b5-9029-ca93826c1e80"}, {"name": "陈智", "aliases": ["陳智"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统元年（年号对照1436年）六月，陈智出任右都御史。", "biography": null, "status": "draft", "id": "6246fdb6-8ccb-5700-8d07-aeb13aee1e89"}, {"name": "黎利", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "黎利在交阯起兵。", "biography": null, "status": "draft", "id": "c3cb3b52-845e-5798-86eb-c3dfdd072dcd"}, {"name": "张瑛（明代内阁大学士）", "aliases": ["張瑛"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，宣德元年（1426年）三月，张瑛升任礼部左侍郎，兼华盖殿大学士。", "biography": null, "status": "draft", "id": "1dc10e08-8b52-5d1a-a0db-a6d37e099403"}, {"name": "王通（明代成山侯）", "aliases": ["成山侯"], "era": "明", "birth_year": null, "death_year": null, "description": "王通赴陕西赈济饥民。", "biography": null, "status": "draft", "id": "f94e24e9-3278-51e4-895d-513be2a33e0d"}, {"name": "陈洽", "aliases": ["陳洽"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，永乐13年（年号对照1415年）四月，陈洽出任兵部尚书，参赞交阯军务。", "biography": null, "status": "draft", "id": "0334cd06-2e5a-5ea9-90c3-8bb994c48b95"}, {"name": "朱高煦", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "汉王。宣德元年（年号对照1426年），本表记录了朱高煦的活动。", "biography": null, "status": "draft", "id": "b6d6c246-3315-52c1-b7c1-e0ebc937a6ce"}, {"name": "李时勉", "aliases": ["李懋"], "era": "明", "birth_year": null, "death_year": null, "description": "李时勉以侍读身份被下狱。", "biography": null, "status": "draft", "id": "c925d68f-aef6-5e23-93cb-cd7a19e52416"}, {"name": "沐晟", "aliases": ["沐景茂"], "era": "明", "birth_year": null, "death_year": null, "description": "沐晟率军在爱子江交战。", "biography": null, "status": "draft", "id": "525263d4-8c61-52a8-a6e9-265b6ac50d2a"}, {"name": "柳升", "aliases": ["安远侯"], "era": "明", "birth_year": null, "death_year": null, "description": "柳升以安远侯身份率领大营。", "biography": null, "status": "draft", "id": "14f79103-5514-5b8a-b46f-74887204ab53"}, {"name": "李庆（明代官员）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，永乐18年（年号对照1420年）十二月，李庆出任工部尚书。", "biography": null, "status": "draft", "id": "71a02ba9-f883-5c28-9f7d-f096e9ad8b22"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱瞻基随明成祖到北京，察看农具和农家生活", "description": "永乐七年，朱瞻基随明成祖朱棣到北京。朱棣让他察看农具和农家的衣食，并写《务本训》给他。 按原历纪年，事情发生在公元1409至1410年之间。", "start_year": null, "end_year": null, "time_original": "永乐七年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fd3c26f3-1199-502e-a17a-1841691f1820"}, {"title": "夏原吉辅导皇长孙，仍兼理行在的吏部、户部和兵部事务", "description": "永乐8年（年号对照1410年）二月，夏原吉辅导皇长孙，仍兼理行在的吏部、户部和兵部事务。", "start_year": 1410, "end_year": 1410, "time_original": "永乐8年（年号对照1410年）二月；公元年核为1410年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "1a55b513-e738-5ad2-8f8d-ff631be9a600"}, {"title": "朱瞻基被正式册立为皇太孙", "description": "永乐九年十一月丁卯，明成祖册立皇长孙朱瞻基为皇太孙。", "start_year": 1411, "end_year": 1411, "time_original": "永乐九年十一月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1c08e7e0-6898-5def-8145-a60e5d822ad2"}, {"title": "皇太子朱瞻基奉命拜谒孝陵并留守南京", "description": "洪熙元年四月壬子，明仁宗命皇太子朱瞻基前往孝陵拜谒，随后留守南京。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年四月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a5bb717a-17d6-556f-ab98-4cc0d4a37e54"}, {"title": "明仁宗患病，派人召在南京的皇太子", "description": "洪熙元年五月庚辰，明仁宗朱高炽身体不适，派使者到南京召皇太子朱瞻基。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年五月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "41843872-9123-5419-a504-17e344300beb"}, {"title": "朱瞻基到良乡受遗诏，入宫发丧", "description": "洪熙元年六月辛丑，皇太子朱瞻基返回到良乡，接到明仁宗的遗诏，随后入宫发丧。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年六月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5e8db225-1376-5009-90cf-c43b0928c15c"}, {"title": "朱瞻基即皇帝位", "description": "洪熙元年（1425年）六月，朱瞻基即皇帝位。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年（1425年）六月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "7453f899-48a0-56ad-ad27-fb3981b8ecae"}, {"title": "明宣宗大赦天下，定次年为宣德元年", "description": "洪熙元年六月，明宣宗朱瞻基即位后大赦天下，定次年为宣德元年。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "49ba8a50-6adf-5a9c-a620-a90915b5415b"}, {"title": "明宣宗命边地将领加强防备", "description": "洪熙元年六月辛亥，明宣宗朱瞻基告谕边境将领严加守备。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年六月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "099369fc-f1ed-5750-be1b-a0cf7ab40864"}, {"title": "明宣宗催外出采办的宦官回京，停止采购", "description": "洪熙元年六月甲寅，明宣宗催促外出采办的宦官返回，并停止他们所经办的采购事项。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年六月甲寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4b0aefd1-4200-5783-b6cf-bf8b8ced406a"}, {"title": "明宣宗尊张氏为皇太后，册立胡氏为皇后", "description": "洪熙元年七月乙亥，明宣宗朱瞻基尊明仁宗的皇后张氏为皇太后，立妃胡氏为皇后。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年七月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c9b45985-bcda-5c26-be06-ee13b0482ccd"}, {"title": "顾兴祖出兵平息大藤峡战事", "description": "洪熙元年七月辛卯，镇远侯顾兴祖出兵征讨大藤峡一带反抗明廷的居民，本纪记战事平息。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年七月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "34bf87a4-5418-5afc-b0e6-aa4d180b87ed"}, {"title": "明宣宗命司法官谨慎处理刑狱", "description": "洪熙元年七月乙未，明宣宗朱瞻基告谕主管司法的官署，审理刑事案件要谨慎。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年七月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "20aa2578-52eb-51d0-9272-9418f1bd901b"}, {"title": "薛贵、吴成等率军巡边", "description": "洪熙元年闰七月戊申，安顺伯薛贵、清平伯吴成、都督马英和都指挥梁成率军巡查边境。卷末校记说明「吴成」原误作「吴诚」。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年闰七月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "623b9bc8-f00a-542d-befb-b21accbd1f3a"}, {"title": "杨溥以太常卿兼翰林学士身份共同处理内阁事务", "description": "洪熙元年（1425年）闰七月，杨溥以太常卿兼翰林学士身份共同处理内阁事务。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年（1425年）闰七月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "26fae369-a089-5f8b-9147-d47ba258bb96"}, {"title": "李英在安定、曲先出兵，安定王到朝廷谢罪", "description": "洪熙元年八月戊辰，明廷的都指挥李英率兵攻打安定、曲先一带反抗明廷的部众，取得胜利。本纪接着记安定王桑儿加失夹来到朝廷谢罪。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年八月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1a308217-cd80-5093-bef3-1df2d1d16bc1"}, {"title": "明宣宗命官员推举适合管理地方的人才", "description": "洪熙元年八月壬申，明宣宗要求中央和地方官员推举廉洁公正、适合治理地方的人。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年八月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ab7f4949-3658-53a9-ad79-162745a110a4"}, {"title": "胡概、叶春奉命巡抚南畿和浙江", "description": "洪熙元年八月癸未，朝廷派大理卿胡概与参政叶春巡抚南畿、浙江。《明史》卷九把此事记为设置巡抚的开端。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年八月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9a4e14cb-59d2-594f-ab9a-8929025e0eee"}, {"title": "明仁宗朱高炽正式安葬在献陵", "description": "洪熙元年九月壬寅，明廷将谥号为昭皇帝的明仁宗朱高炽安葬在献陵。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年九月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "58f97b96-c829-5941-92b5-fd8232c93dd7"}, {"title": "南京发生地震", "description": "洪熙元年十月戊寅，南京发生地震。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年十月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6cf1f6e3-e4f5-5715-8b05-4beff46f27ac"}, {"title": "明宣宗命勋臣与各署官员复审重罪案件", "description": "洪熙元年十月戊子，明宣宗朱瞻基命公侯伯、五府六部官员、大学士及给事中共同复核在押重罪人员的案件。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年十月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ad56fe21-8886-5a1f-bee6-b095cccefabd"}, {"title": "顾兴祖率军平息思恩战事", "description": "洪熙元年十一月戊戌，本纪记顾兴祖率军征讨思恩一带反抗明廷的居民，战事平息。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年十一月戊戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "652e9302-7a01-50b7-b3d3-8cdaca2f074a"}, {"title": "薛禄任镇朔大将军，率军巡边", "description": "洪熙元年十一月辛酉，明廷任命薛禄为镇朔大将军，率军巡查边境。", "start_year": 1426, "end_year": 1426, "time_original": "洪熙元年十一月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8c3ee6a3-03c3-538f-958d-ff0df7fbbcf6"}, {"title": "顾兴祖率军平息宜山战事", "description": "洪熙元年十二月甲申，本纪记顾兴祖率军征讨宜山一带反抗明廷的居民，战事平息。", "start_year": 1426, "end_year": 1426, "time_original": "洪熙元年十二月甲申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "44c62a5e-e4fb-548c-830e-c100a2157748"}, {"title": "本纪汇记洪熙元年多地入贡", "description": "洪熙元年，哈密回回、满剌撒丁、占城、琉球中山、爪哇、乌斯藏、瓦剌和浡泥入贡。卷九在年末汇记各次来使。 按原历纪年，事情发生在公元1425至1426年之间。", "start_year": null, "end_year": null, "time_original": "洪熙元年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "894ea863-d76f-59c2-9015-3750d5bed5cf"}, {