le": "明廷免除山东夏税", "description": "宣德元年七月乙未，朝廷免征山东的夏税。", "start_year": 1426, "end_year": 1426, "time_original": "宣德元年七月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cca87efa-0d30-583b-ad88-cb2550739acc"}, {"title": "明宣宗规定宦官传旨须复奏后执行", "description": "宣德元年七月己亥，明宣宗朱瞻基告谕六科，凡宦官传达的旨意，必须再向皇帝上奏确认，然后执行。", "start_year": 1426, "end_year": 1426, "time_original": "宣德元年七月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0a55594d-d5ce-5dd8-8e02-7b7c98abd606"}, {"title": "明廷停止在湖广采木", "description": "宣德元年七月壬子，朝廷停止在湖广地区采集木材。", "start_year": 1426, "end_year": 1426, "time_original": "宣德元年七月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2c7774db-396c-538d-aa77-320adfb308e6"}, {"title": "汉王朱高煦起兵反抗明廷", "description": "宣德元年八月壬戌，汉王朱高煦起兵反抗明廷。", "start_year": 1426, "end_year": 1426, "time_original": "宣德元年八月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a1987dc3-5ddd-52e8-84c2-8c621ecb30bd"}, {"title": "明廷赦免获死罪以下的武臣并恢复官职", "description": "宣德元年八月丙寅，朝廷赦免获死罪及以下罪名的武臣，使他们恢复原职。", "start_year": 1426, "end_year": 1426, "time_original": "宣德元年八月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1ce14499-e7f6-530d-9cea-7af498335ec4"}, {"title": "明宣宗决定亲征朱高煦，部署留守和前锋", "description": "宣德元年八月己巳，明宣宗朱瞻基决定亲征朱高煦，命郑王朱瞻埈和襄王朱瞻墡留守，薛禄、吴成率领前锋，并赏赐五军将士。", "start_year": 1426, "e