SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "person", "field_path": "description", "claim_text": "朱瞻基随明成祖到北京。", "citation": "《明史》卷9·本纪第九·宣宗·mingshi-2f603db3d81e-p001289；永乐七年", "note": "原文：永樂七年，從幸北京，令觀農具及田家衣食，作務本訓授之；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "0754334a-bced-5e68-8cf3-7d77c6fde2ea", "subject_id": "888fc961-674c-52bf-b645-1351d5637434", "source_id": "3b47e98e-083d-5a45-a349-517a01990909"}, {"subject_table": "person", "field_path": "description", "claim_text": "朱棣让朱瞻基了解农家生活并赐《务本训》。", "citation": "《明史》卷9·本纪第九·宣宗·mingshi-2f603db3d81e-p001289；永乐七年", "note": "原文：永樂七年，從幸北京，令觀農具及田家衣食，作務本訓授之；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "0da0cdc6-304e-52cd-96ae-23cc6ca7352e", "subject_id": "dd806a37-77e8-5244-96e9-4d71db81b600", "source_id": "3b47e98e-083d-5a45-a349-517a01990909"}, {"subject_table": "event", "field_path": "description", "claim_text": "永乐七年，朱瞻基随明成祖朱棣到北京。朱棣让他察看农具和农家的衣食，并写《务本训》给他。 按原历纪年，事情发生在公元1409至1410年之间。", "citation": "《明史》卷9·本纪第九·宣宗·mingshi-2f603db3d81e-p001289；永乐七年", "note": "原文：永樂七年，從幸北京，令觀農具及田家衣食，作務本訓授之；核对说明：该摘录逐字支持所列行动及其阶段；时间取本段及相邻年条。", "status": "draft", "id": "b1dc8542-4874-5978-be4f-59da2a4bafe5", "subject_id": "fd3c26f3-1199-502e-a17a-1841691f1820", "source_id": "3b47e98e-083d-5a45-a349-517a01990909"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "原历永乐七年。DDBC历表换算所据为1409-01-25至1410-02-12，据此核对公元发生年份。", "citation": "《明史》卷9·本纪第九·宣宗·mingshi-2f603db3d81e-p001289；永乐七年", "note": "原文：永樂七年，從幸北京，令觀農具及田家衣食，作務本訓授之；核对说明：原历纪年按本段及相邻年条核对，史料未载的具体日保留为空。", "status": "draft", "id": "960e465d-5440-5304-8b4e-7597fbd3919e", "subject_id": "fd3c26f3-1199-502e-a17a-1841691f1820", "source_id": "3b47e98e-083d-5a45-a349-517a01990909"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "随明成祖到北京", "citation": "《明史》卷9·本纪第九·宣宗·mingshi-2f603db3d81e-p00128